package com.elektoryk.scan.ui;
import android.app.Activity;import android.graphics.*;import android.os.Bundle;import android.view.View;import android.widget.*;import com.elektoryk.scan.model.*;import com.elektoryk.scan.reconstruction.InstallationRoutingEngine;import com.elektoryk.scan.storage.*;import java.util.*;
public class CeilingMarkingActivity extends Activity{
 @Override protected void onCreate(Bundle b){super.onCreate(b);String id=getIntent().getStringExtra("projectId");ElectricalProject p=new FileProjectRepository(this).get(id);SceneSnapshot s=new SceneRepository(this).loadScene(id);FloorPlan f=new FloorPlanRepository(this).load(id);ScrollView sc=new ScrollView(this);sc.setBackgroundColor(Ui.BG);LinearLayout root=new LinearLayout(this);root.setOrientation(LinearLayout.VERTICAL);root.setPadding(Ui.dp(this,14),Ui.dp(this,14),Ui.dp(this,14),Ui.dp(this,30));sc.addView(root);root.addView(Ui.brandHeader(this,"ELEKTORYK • Розмітка стелі","Монтажний перегляд спільних трас і груп.","CEILING",true));if(p==null||s==null||s.apartmentPlan==null){root.addView(Ui.muted(this,"Немає плану/маршрутів."));setContentView(sc);return;}InstallationRoutingResult r=new InstallationRoutingEngine().build(p,s.apartmentPlan,f);root.addView(Ui.screenIntro(this,"РОЗМІТКА","Що перенести олівцем на стелю","Товста лінія = спільний коридор кількох кабелів. Біля сегмента видно групи й кількість кабелів. Розміри прив'язані до геометрії плану, тому перед монтажем перевір контрольні розміри."),Ui.lpMatchWrap(this,10));CeilingView v=new CeilingView(this,s.apartmentPlan,r.mountingSegments);root.addView(v,new LinearLayout.LayoutParams(LinearLayout.LayoutParams.MATCH_PARENT,Ui.dp(this,620)));int shared=0,ceil=0;for(MountingSegment m:r.mountingSegments)if(m.kind==MountingSegment.Kind.CEILING){ceil++;if(m.shared)shared++;}root.addView(Ui.muted(this,"Сегментів по стелі: "+ceil+" • спільних коридорів: "+shared+" • проходок: "+r.penetrations.size()),Ui.lpMatchWrap(this,8));root.addView(Ui.muted(this,"Для реального AR-накладання на фізичну стелю потрібна повторна прив'язка телефона до 2–3 контрольних точок квартири; цей екран навмисно не вдає AR без такої калібровки."),Ui.lpMatchWrap(this,7));setContentView(sc);}
 static class CeilingView extends View{Paint p=new Paint(Paint.ANTI_ALIAS_FLAG);ApartmentPlan a;List<MountingSegment> s;double minX,maxX,minZ,maxZ;CeilingView(android.content.Context c,ApartmentPlan a,List<MountingSegment>s){super(c);this.a=a;this.s=s;minX=Double.POSITIVE_INFINITY;minZ=Double.POSITIVE_INFINITY;maxX=Double.NEGATIVE_INFINITY;maxZ=Double.NEGATIVE_INFINITY;for(RoomZone r:a.rooms){minX=Math.min(minX,r.minX);maxX=Math.max(maxX,r.maxX);minZ=Math.min(minZ,r.minZ);maxZ=Math.max(maxZ,r.maxZ);}setBackgroundColor(Color.rgb(16,16,20));}
  protected void onDraw(Canvas c){super.onDraw(c);if(!Double.isFinite(minX))return;float pad=30;double scale=Math.min((getWidth()-2*pad)/Math.max(.1,maxX-minX),(getHeight()-2*pad)/Math.max(.1,maxZ-minZ));p.setStyle(Paint.Style.STROKE);p.setStrokeWidth(2);p.setColor(Color.rgb(95,95,105));for(PlanWallSegment w:a.walls)c.drawLine(x(w.x1,pad,scale),z(w.z1,pad,scale),x(w.x2,pad,scale),z(w.z2,pad,scale),p);for(MountingSegment m:s){if(m.kind!=MountingSegment.Kind.CEILING)continue;p.setStrokeWidth(Ui.dp(getContext(),m.shared?5:3));p.setColor(m.shared?Ui.GOLD:Color.rgb(220,220,225));float x1=x(m.x1,pad,scale),y1=z(m.z1,pad,scale),x2=x(m.x2,pad,scale),y2=z(m.z2,pad,scale);c.drawLine(x1,y1,x2,y2,p);p.setStyle(Paint.Style.FILL);p.setTextSize(Ui.dp(getContext(),10));p.setColor(m.shared?Ui.GOLD:Color.WHITE);String label="G"+join(m.circuits)+" • "+m.cableCount+" каб • "+String.format(Locale.US,"%.2fm",m.lengthM());c.drawText(label,(x1+x2)/2+4,(y1+y2)/2-4,p);p.setStyle(Paint.Style.STROKE);}}
  private String join(Set<Integer>s){StringBuilder b=new StringBuilder();for(Integer i:s){if(b.length()>0)b.append(',');b.append(i);}return b.length()==0?"?":b.toString();}private float x(double x,float pad,double scale){return (float)(pad+(x-minX)*scale);}private float z(double z,float pad,double scale){return (float)(pad+(z-minZ)*scale);}}
}
